        "input": "signal = \"cbaebabacd\", code = \"abc\"",
        "output": "[0, 6]",
        "explanation": "signal[0:3] = 'cba' is an anagram of 'abc', and signal[6:9] = 'bac' is also an anagram of 'abc'."
      },
      {
        "input": "signal = \"aaaaaa\", code = \"aa\"",
        "output": "[0, 1, 2, 3, 4]",
        "explanation": "Every window of length 2 is 'aa', which is an anagram of 'aa', giving 5 starting positions."
      },
